mapper.select:
select from product_sku sku inner join product p on p.id = sku.product_id where sku.status = 1 and sku.is_deleted = 0 and p.status = 1 and p.audit_status = 1 and p.is_deleted = 0
and (p.name like concat('%', #{keyword}, '%') or sku.sku_name like concat('%', #{keyword}, '%'))
order by sku.sale_num desc, sku.id asc limit #{limit}
